using Godot;
using System;
using System.Collections.Generic;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsGeometryOperations:RefCounted
{
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var result)?result:fallback;
    private static bool IsActor(Node node){var script=node.GetScript().As<Script>();while(script!=null){if(script.ResourcePath=="res://scripts/actors/core/ActorRuntime.cs")return true;script=script.GetBaseScript();}return false;}
    public PrimitiveMesh primitive(Node runtime,Settings values){PrimitiveMesh mesh=Get(values,"shape",0).AsInt32() switch{1=>new SphereMesh(),2=>new CylinderMesh(),3=>new CapsuleMesh(),4=>new PlaneMesh(),5=>new PrismMesh(),6=>new QuadMesh(),7=>new TorusMesh(),_=>new BoxMesh()};runtime.Call("_apply_shape_properties",mesh,values);return mesh;}
    public GArray meshes(Node runtime,Settings physicsIds){var result=new GArray();foreach(var child in runtime.GetChildren()){if(child.GetMeta("kiwi_physics_excluded",false).AsBool())continue;if(IsActor(child)&&physicsIds.ContainsKey(child.Get("actor").As<Resource>().Get("id")))continue;if(child is MeshInstance3D mesh&&mesh.Mesh!=null&&(mesh.Layers&1)!=0)result.Add(mesh);foreach(var nested in meshes(child,physicsIds))result.Add(nested);}return result;}
    public Settings capture(Node runtime,Settings physicsIds)
    {
        var inverse=runtime.Call("remote_transform").AsTransform3D().AffineInverse();var items=new GArray();var points=new List<Vector3>();var bounds=new Aabb();bool first=true;foreach(var value in meshes(runtime,physicsIds)){var node=value.As<MeshInstance3D>();Node? owner=node.GetParent();while(owner!=null&&!IsActor(owner))owner=owner.GetParent();var local=inverse*node.GlobalTransform;var mesh=node.Mesh!;var original=mesh;bool isPrimitive=owner!=null&&owner.Get("actor").As<Resource>().Get("type_id").AsString()=="basic_shape"&&node==owner.Get("content").AsGodotObject();if(isPrimitive)mesh=primitive(owner!,owner!.Get("actor").As<Resource>().Get("values").AsGodotDictionary());var box=local*mesh.GetAabb();bounds=first?box:bounds.Merge(box);first=false;var surfaces=new GArray();var materials=new GArray();for(int surface=0;surface<mesh.GetSurfaceCount();surface++){if(mesh is ArrayMesh arrayMesh&&arrayMesh.SurfaceGetPrimitiveType(surface)!=Mesh.PrimitiveType.Triangles)continue;var data=mesh.SurfaceGetArrays(surface);if(data.Count!=(int)Mesh.ArrayType.Max)continue;surfaces.Add(data);var material=node.GetActiveMaterial(surface);materials.Add(material==null?default(Variant):Variant.From(material));foreach(var vertex in data[(int)Mesh.ArrayType.Vertex].AsVector3Array())points.Add(local*vertex);}var item=new Settings{["node"]=node,["original"]=original,["skin"]=node.Skin==null?default(Variant):Variant.From(node.Skin),["local"]=local,["surfaces"]=surfaces,["materials"]=materials,["visible"]=node.Visible,["primitive"]=isPrimitive,["actor_id"]=(owner??runtime).Get("actor").As<Resource>().Get("id"),["owner_local"]=owner!=null?owner.Call("remote_transform").AsTransform3D().AffineInverse()*node.GlobalTransform:local};if(mesh.HasMeta("kiwi_collision_faces"))item["collision_faces"]=mesh.GetMeta("kiwi_collision_faces");if(mesh.HasMeta("kiwi_compound_points"))item["compound_points"]=mesh.GetMeta("kiwi_compound_points");if(mesh.HasMeta("kiwi_editable_topology"))item["polygon"]=mesh.GetMeta("kiwi_editable_topology");items.Add(item);}if(first)bounds=new Aabb(new Vector3(-.5f,-.5f,-.5f),Vector3.One);return prepare_collision(new Settings{["meshes"]=items,["points"]=points.ToArray(),["bounds"]=bounds});
    }
    private static Vector3[] CollisionVertices(Settings item){if(item.ContainsKey("collision_faces"))return item["collision_faces"].AsVector3Array();var vertices=new List<Vector3>();foreach(var value in item["surfaces"].AsGodotArray())vertices.AddRange(value.AsGodotArray()[(int)Mesh.ArrayType.Vertex].AsVector3Array());return vertices.ToArray();}
    public Settings prepare_collision(Settings geometry)
    {
        var items=Get(geometry,"meshes",new GArray()).AsGodotArray();if(items.Any(value=>value.AsGodotDictionary().ContainsKey("collision_faces"))){var points=new List<Vector3>();var bounds=new Aabb();bool first=true;foreach(var value in items){var item=value.AsGodotDictionary();var transform=item["local"].AsTransform3D();foreach(var vertex in CollisionVertices(item)){var point=transform*vertex;points.Add(point);bounds=first?new Aabb(point,Vector3.Zero):bounds.Expand(point);first=false;}}if(!first){geometry["collision_points"]=points.ToArray();geometry["collision_bounds"]=bounds;}}
        if(items.Any(value=>value.AsGodotDictionary().ContainsKey("compound_points"))){var pieces=new GArray();foreach(var value in items){var item=value.AsGodotDictionary();var parts=Get(item,"compound_points",new GArray()).AsGodotArray();if(!item.ContainsKey("compound_points"))parts=new GArray{CollisionVertices(item)};foreach(var part in parts){var points=part.AsVector3Array();if(points.Length<4)continue;var transform=item["local"].AsTransform3D();for(int i=0;i<points.Length;i++)points[i]=transform*points[i];pieces.Add(points);}}geometry["compound_points"]=pieces;}return geometry;
    }
    public Settings collider(Settings geometry,Settings settings)
    {
        var bounds=Get(geometry,"collision_bounds",geometry["bounds"]).AsAabb();var size=bounds.Size.Max(Vector3.One*.005f);int choice=settings["shape"].AsInt32(),body=settings["body_mode"].AsInt32();Shape3D? shape=null;var offset=new Transform3D(Basis.Identity,bounds.GetCenter());var parts=Get(geometry,"compound_points",new GArray()).AsGodotArray();bool compoundChoice=choice==0||choice==6&&body!=1;if(geometry.ContainsKey("compound_points")&&compoundChoice&&parts.Count<=512){var shapes=new GArray();foreach(var value in parts){var hull=new ConvexPolygonShape3D{Points=value.AsVector3Array()};shapes.Add(new Settings{["shape"]=hull,["offset"]=Transform3D.Identity});}if(shapes.Count>0)return new Settings{["shape"]=shapes[0].AsGodotDictionary()["shape"],["offset"]=Transform3D.Identity,["compound"]=shapes};}
        switch(choice){case 2:shape=new SphereShape3D{Radius=Math.Max(size.X,Math.Max(size.Y,size.Z))*.5f};break;case 3:float capsuleRadius=Math.Max(size.X,size.Z)*.5f;shape=new CapsuleShape3D{Radius=capsuleRadius,Height=Math.Max(size.Y,capsuleRadius*2)};break;case 4:shape=new CylinderShape3D{Radius=Math.Max(size.X,size.Z)*.5f,Height=size.Y};break;case 5:var points=Get(geometry,"collision_points",geometry["points"]).AsVector3Array();if(points.Length>=4){shape=new ConvexPolygonShape3D{Points=points};offset=Transform3D.Identity;}break;case 6:if(body==1){var faces=new List<Vector3>();foreach(var value in geometry["meshes"].AsGodotArray()){var item=value.AsGodotDictionary();var transform=item["local"].AsTransform3D();if(item.ContainsKey("collision_faces")){foreach(var vertex in item["collision_faces"].AsVector3Array())faces.Add(transform*vertex);continue;}foreach(var surface in item["surfaces"].AsGodotArray()){var arrays=surface.AsGodotArray();var indices=arrays[(int)Mesh.ArrayType.Index].VariantType==Variant.Type.Nil?Array.Empty<int>():arrays[(int)Mesh.ArrayType.Index].AsInt32Array();var vertices=arrays[(int)Mesh.ArrayType.Vertex].AsVector3Array();for(int i=0;i<(indices.Length>0?indices.Length:vertices.Length);i++)faces.Add(transform*vertices[indices.Length>0?indices[i]:i]);}}if(faces.Count>0){var concave=new ConcavePolygonShape3D{BackfaceCollision=true};concave.SetFaces(faces.ToArray());shape=concave;offset=Transform3D.Identity;}}break;}
        shape??=new BoxShape3D{Size=size};return new Settings{["shape"]=shape,["offset"]=offset,["error"]=parts.Count>512&&compoundChoice?"Compound collision exceeds 512 pieces. Use static mesh collision or instantiate the model as separate actors.":""};
    }
}
